-- C-04: classes and cost centers; preserve audited UP reassignment.
set local lock_timeout='5s';set local statement_timeout='60s';
-- Internal centers carry their own department instead of a customer department.
do $patch$declare source text;begin source:=pg_get_functiondef('asset_posting_private.dimensions(bigint,bigint,bigint)'::regprocedure);if position('p_department is null or cu.department_id=p_department'in source)=0 then raise exception 'Unexpected dimensions definition';end if;execute replace(source,'p_department is null or cu.department_id=p_department','p_department is null or(case when c.cost_center_type=''INTERNO''then c.department_id else cu.department_id end)=p_department');end$patch$;
do $patch$declare source text;begin source:=pg_get_functiondef('supplier_invoice_private.save_supplier_invoice_without_withholding(jsonb,bigint)'::regprocedure);if position('cost_centers cc join customers c on c.customer_id=cc.customer_id'in source)=0 then raise exception 'Unexpected supplier cost center guard';end if;source:=replace(source,'cost_centers cc join customers c on c.customer_id=cc.customer_id','cost_centers cc left join customers c on c.customer_id=cc.customer_id');source:=replace(source,'and c.department_id=(line->>''department_id'')::bigint','and(case when cc.cost_center_type=''INTERNO''then cc.department_id else c.department_id end)=(line->>''department_id'')::bigint');execute source;end$patch$;
create schema cost_center_master_private;revoke all on schema cost_center_master_private from public,anon,authenticated,service_role;grant usage on schema cost_center_master_private to authenticated;
create or replace function organization_master_private.meta(k text)returns table(t text,pk text,links text,fields text[])language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.links,c.fields from(values
 ('departments','departments','department_id','department_subsidiaries',array['name','type','parent_id','is_inactive']),
 ('locations','locations','location_id','location_subsidiaries',array['name','parent_id','country_id']),
 ('classes','classes','class_id','class_subsidiaries',array['name','parent_id','description','is_inactive']),
 ('cost-centers','cost_centers','cost_center_id',null,array['name','subsidiary_id','cost_center_type','customer_id','department_id','class_id','up_approver_id']))c(k,t,pk,links,fields)where c.k=$1$$;
-- Extend the tested hierarchy engine without changing departments/locations.
do $patch$declare source text;begin
 source:=pg_get_functiondef('public.save_organization_master(text,jsonb,bigint)'::regprocedure);
 if position('else if data->>''country_id''is null' in source)=0 then raise exception 'Unexpected organization save definition';end if;
 source:=replace(source,'else if data->>''country_id''is null','elsif p_catalog=''classes''then if jsonb_typeof(data->''is_inactive'')is distinct from''boolean''or(data->>''description''is not null and(jsonb_typeof(data->''description'')is distinct from''string''or length(data->>''description'')>4000))then raise exception using errcode=''22023'',message=''Descripción u opción de clase inválida.'';end if;else if data->>''country_id''is null');
 source:=replace(source,'or(p_catalog=''locations''and parentrow','or(p_catalog=''classes''and coalesce((parentrow->>''is_inactive'')::boolean,false))or(p_catalog=''locations''and parentrow');
 source:=replace(source,'or(p_catalog=''locations''and oldrow','or(p_catalog=''classes''and not coalesce((oldrow->>''is_inactive'')::boolean,false)and(data->>''is_inactive'')::boolean)or(p_catalog=''locations''and oldrow');
 execute source;
end$patch$;
create function cost_center_master_private.visible(sid bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return sid=entity_master_private.identity()and organization_master_private.allowed('cost-centers','view');exception when insufficient_privilege then return false;end$$;
create function cost_center_master_private.dto(c public.cost_centers)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select to_jsonb(c)||jsonb_build_object('_revision',md5(to_jsonb(c)::text),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed('cost-centers','edit'),'canDelete',organization_master_private.allowed('cost-centers','delete')and not entity_master_private.used('cost_centers',c.cost_center_id)))$$;
create function cost_center_master_private.list()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access('cost-centers','view');begin return coalesce((select jsonb_agg(cost_center_master_private.dto(c)order by c.cost_center_id)from public.cost_centers c where c.subsidiary_id=sid),'[]');end$$;
create function cost_center_master_private.options()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access('cost-centers','view');begin return jsonb_build_object('canView',true,'canCreate',organization_master_private.allowed('cost-centers','create'),'canEdit',organization_master_private.allowed('cost-centers','edit'),'canDelete',organization_master_private.allowed('cost-centers','delete'),'references',jsonb_build_object(
 'organization/subsidiaries',(select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name))from public.subsidiaries s where s.subsidiary_id=sid),
 'entities/customers',coalesce((select jsonb_agg(jsonb_build_object('customer_id',c.customer_id,'company_name',c.company_name,'department_id',c.department_id,'subsidiary_id',sid))from public.customers c where exists(select 1 from public.entity_subsidiaries e where e.customer_id=c.customer_id and e.subsidiary_id=sid)),'[]'),
 'organization/departments',coalesce((select jsonb_agg(jsonb_build_object('department_id',d.department_id,'name',d.name,'type',d.type,'subsidiary_id',sid))from public.departments d where not d.is_inactive and(sid=any(organization_master_private.scope_ids('departments',d.department_id)))),'[]'),
 'organization/classes',coalesce((select jsonb_agg(jsonb_build_object('class_id',c.class_id,'name',c.name,'subsidiary_id',sid))from public.classes c where not c.is_inactive and sid=any(organization_master_private.scope_ids('classes',c.class_id))),'[]'),
 'organization/up-approver-options',coalesce((select jsonb_agg(jsonb_build_object('id',u.user_id,'name',btrim(concat_ws(' ',u.first_name,u.last_name)),'email',u.email))from public.users u join public.user_subsidiaries us using(user_id)where us.subsidiary_id=sid and u.is_active),'[]')));end$$;
create function cost_center_master_private.save(p jsonb,id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access('cost-centers',case when id is null then'create'else'edit'end);oldrow public.cost_centers;c public.cost_centers;data jsonb;k text;used boolean;fields text[]:=array['name','subsidiary_id','cost_center_type','customer_id','department_id','class_id','up_approver_id'];begin
 if id<=0 or id>9007199254740991 or jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>32000 or exists(select 1 from jsonb_object_keys(p)x where not x=any(fields||array['_revision']))then raise exception using errcode='22023',message='Campos de centro de costo inválidos.';end if;
 perform pg_advisory_xact_lock(793148,1);perform pg_advisory_xact_lock(793147,1);
 if id is not null then select *into oldrow from public.cost_centers where cost_center_id=id for update;if not found or oldrow.subsidiary_id<>sid then raise exception using errcode='42501',message='Centro de costo fuera de la filial activa.';end if;if p->>'_revision'is distinct from md5(to_jsonb(oldrow)::text)then raise exception using errcode='55000',message='El centro cambió. Consúltelo nuevamente.';end if;end if;
 data:=case when id is null then jsonb_build_object('subsidiary_id',sid)else to_jsonb(oldrow)end||(p-'_revision');
 if jsonb_typeof(data->'name')is distinct from'string'or nullif(btrim(data->>'name'),'')is null or length(btrim(data->>'name'))>250 or coalesce(data->>'cost_center_type','')not in('CLIENTE','INTERNO')then raise exception using errcode='22023',message='Nombre o tipo de centro inválido.';end if;data:=data||jsonb_build_object('name',btrim(data->>'name'));
 foreach k in array array['subsidiary_id','customer_id','department_id','class_id','up_approver_id']loop if data->>k=''then data:=jsonb_set(data,array[k],'null');end if;if data->>k is not null and(data->>k!~'^[1-9][0-9]{0,15}$'or(data->>k)::numeric>9007199254740991)then raise exception using errcode='22023',message='Referencia inválida.';end if;end loop;
 c:=jsonb_populate_record(null::public.cost_centers,data);if c.subsidiary_id is distinct from sid then raise exception using errcode='42501',message='Mantenga el centro en la filial activa.';end if;
 if c.cost_center_type='CLIENTE'then if c.customer_id is null or not exists(select 1 from public.customers x join public.entity_subsidiaries e using(customer_id)where x.customer_id=c.customer_id and e.subsidiary_id=sid and x.department_id=c.department_id)then raise exception using errcode='42501',message='Cliente o departamento de cliente no disponibles.';end if;
 elsif c.customer_id is not null or c.up_approver_id is not null then raise exception using errcode='22023',message='El centro interno no admite cliente ni aprobador UP propio.';end if;
 if c.department_id is null or not exists(select 1 from public.departments d where d.department_id=c.department_id and not d.is_inactive and lower(d.type)=lower(c.cost_center_type)and sid=any(organization_master_private.scope_ids('departments',d.department_id)))then raise exception using errcode='42501',message='Departamento incompatible con el centro.';end if;
 if c.class_id is not null and not exists(select 1 from public.classes cl where cl.class_id=c.class_id and not cl.is_inactive and sid=any(organization_master_private.scope_ids('classes',cl.class_id)))then raise exception using errcode='42501',message='Clase fuera del alcance.';end if;
 if c.up_approver_id is not null and not exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=c.up_approver_id and us.subsidiary_id=sid and u.is_active)then raise exception using errcode='42501',message='Aprobador no disponible.';end if;
 if c.up_approver_id is distinct from oldrow.up_approver_id and not public.up_approver_has_permission('ORG_UP_APPROVER_MANAGE')then raise exception using errcode='42501',message='Requiere permiso de gestión de aprobadores UP.';end if;
 if id is not null then used:=entity_master_private.used('cost_centers',id);if used and(c.cost_center_type is distinct from oldrow.cost_center_type or c.customer_id is distinct from oldrow.customer_id or c.department_id is distinct from oldrow.department_id or c.class_id is distinct from oldrow.class_id or c.up_approver_id is distinct from oldrow.up_approver_id)then raise exception using errcode='55000',message='El centro utilizado conserva sus referencias. Reasigne aprobadores mediante el proceso auditado.';end if;end if;
 if id is null then insert into public.cost_centers(name,subsidiary_id,cost_center_type,customer_id,department_id,class_id,up_approver_id)values(c.name,sid,c.cost_center_type,c.customer_id,c.department_id,c.class_id,c.up_approver_id)returning *into c;
 else update public.cost_centers set name=c.name,cost_center_type=c.cost_center_type,customer_id=c.customer_id,department_id=c.department_id,class_id=c.class_id,up_approver_id=c.up_approver_id where cost_center_id=id returning *into c;end if;
 return cost_center_master_private.dto(c);end$$;
create function cost_center_master_private.remove(id bigint,revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access('cost-centers','delete');c public.cost_centers;begin perform pg_advisory_xact_lock(793148,1);select *into c from public.cost_centers where cost_center_id=id for update;if not found or c.subsidiary_id<>sid then raise exception using errcode='42501',message='Centro fuera del alcance.';end if;if revision is distinct from md5(to_jsonb(c)::text)or entity_master_private.used('cost_centers',id)then raise exception using errcode='55000',message='El centro cambió o tiene dependencias.';end if;delete from public.cost_centers where cost_center_id=id;return true;end$$;
alter function public.organization_master_list(text)set schema organization_master_private;
alter function public.organization_master_options(text)set schema organization_master_private;
alter function public.save_organization_master(text,jsonb,bigint)set schema organization_master_private;
alter function public.delete_organization_master(text,bigint,text)set schema organization_master_private;
create function public.organization_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='cost-centers'then return cost_center_master_private.list();end if;return organization_master_private.organization_master_list(p_catalog);end$$;
create function public.organization_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='cost-centers'then return cost_center_master_private.options();end if;return organization_master_private.organization_master_options(p_catalog);end$$;
create function public.save_organization_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='cost-centers'then return cost_center_master_private.save(p_payload,p_id);end if;return organization_master_private.save_organization_master(p_catalog,p_payload,p_id);end$$;
create function public.delete_organization_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='cost-centers'then return cost_center_master_private.remove(p_id,p_revision);end if;return organization_master_private.delete_organization_master(p_catalog,p_id,p_revision);end$$;
alter function public.up_reassign_cost_centers(jsonb)set schema cost_center_master_private;
create function public.up_reassign_cost_centers(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform organization_master_private.access('cost-centers','edit');perform pg_advisory_xact_lock(793148,1);return cost_center_master_private.up_reassign_cost_centers(p);end$$;
do $patch$declare source text;begin source:=pg_get_functiondef('public.up_approver_options()'::regprocedure);if position('''manage'',public.up_approver_has_permission(''ORG_UP_APPROVER_MANAGE'')'in source)=0 then raise exception 'Unexpected UP options definition';end if;execute replace(source,'''manage'',public.up_approver_has_permission(''ORG_UP_APPROVER_MANAGE'')','''manage'',public.up_approver_has_permission(''ORG_UP_APPROVER_MANAGE'')and organization_master_private.allowed(''cost-centers'',''edit'')');end$patch$;
create or replace function public.sync_customer_cost_center_department()returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;begin if new.department_id is distinct from old.department_id then perform pg_advisory_xact_lock(793148,1);for c in select *from public.cost_centers where customer_id=new.customer_id and cost_center_type='CLIENTE'and department_id is distinct from new.department_id for update loop
 if entity_master_private.used('cost_centers',c.cost_center_id)or not organization_master_private.allowed('cost-centers','edit')or not exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=c.subsidiary_id)then raise exception using errcode='55000',message='El cliente tiene centros de costo utilizados o no autorizados. Revise las dependencias antes de cambiar su departamento.';end if;end loop;
 update public.cost_centers set department_id=new.department_id where customer_id=new.customer_id and cost_center_type='CLIENTE'and department_id is distinct from new.department_id;end if;return new;end$$;
do $$declare t text;p record;col record;pred text;begin foreach t in array array['classes','class_subsidiaries','cost_centers']loop
 for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for col in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',col.column_name,col.column_name,col.column_name,col.column_name,t);end loop;
 pred:=case t when'classes'then'organization_master_private.visible(''classes'',class_id)'when'class_subsidiaries'then'organization_master_private.visible(''classes'',class_id)and subsidiary_id=public.active_subsidiary_id()'else'cost_center_master_private.visible(subsidiary_id)'end;
 execute format('create policy cost_class_master_read on public.%I for select to authenticated using(%s)',t,pred);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema cost_center_master_private from public,anon,authenticated,service_role;grant execute on function cost_center_master_private.visible(bigint)to authenticated;
revoke all on function organization_master_private.organization_master_list(text),organization_master_private.organization_master_options(text),organization_master_private.save_organization_master(text,jsonb,bigint),organization_master_private.delete_organization_master(text,bigint,text)from public,anon,authenticated,service_role;
revoke all on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.up_reassign_cost_centers(jsonb)from public,anon,authenticated,service_role;
grant execute on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.up_reassign_cost_centers(jsonb)to authenticated;
-- Only the owner engine may append the reassignment audit.
revoke insert,update,delete,truncate on public.cost_center_up_approver_audit from public,anon,authenticated,service_role;
do $$declare c record;begin for c in select column_name from information_schema.columns where table_schema='public'and table_name='cost_center_up_approver_audit'loop execute format('revoke insert(%I),update(%I)on public.cost_center_up_approver_audit from public,anon,authenticated,service_role',c.column_name,c.column_name);end loop;end$$;
notify pgrst,'reload schema';
